// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title Private Label G2C Contract
 * @author [Your Name]
 * @notice This contract implements a private label solution for G2C (Government-to-Citizen) transactions.
 * @dev This contract uses ERC721 for NFT-based transactions and implements proper access control.
 */
contract PrivateLabelG2C is ERC721, AccessControl {
    using Counters for Counters.Counter;
    Counters.Counter private _tokenIds;

    // Roles
    bytes32 public constant ADMIN = "ADMIN";
    bytes32 public constant GOVERNMENT = "GOVERNMENT";
    bytes32 public constant CITIZEN = "CITIZEN";

    /**
     * @dev Initializes the contract with the given parameters.
     * @param name The name of the token.
     * @param symbol The symbol of the token.
     */
    constructor(string memory name, string memory symbol) ERC721(name, symbol) {
        // Initialize the admin role with the deployer address
        _grantRole(ADMIN, msg.sender);
        _grantRole(GOVERNMENT, msg.sender);
    }

    /**
     * @notice Grants a role to an address.
     * @dev Only the admin can grant roles.
     * @param role The role to grant.
     * @param account The address to grant the role to.
     */
    function grantRole(bytes32 role, address account) public onlyRole(ADMIN) {
        _grantRole(role, account);
        emit RoleGranted(role, account, msg.sender);
    }

    /**
     * @notice Revokes a role from an address.
     * @dev Only the admin can revoke roles.
     * @param role The role to revoke.
     * @param account The address to revoke the role from.
     */
    function revokeRole(bytes32 role, address account) public onlyRole(ADMIN) {
        _revokeRole(role, account);
        emit RoleRevoked(role, account, msg.sender);
    }

    /**
     * @notice Mints a new NFT to a citizen.
     * @dev Only government can mint NFTs.
     * @param to The address of the citizen to mint the NFT to.
     * @param tokenURI The URI of the token metadata.
     */
    function mintNFT(address to, string memory tokenURI) public onlyRole(GOVERNMENT) {
        _tokenIds.increment();
        uint256 newItemId = _tokenIds.current();
        _mint(to, newItemId);
        _setTokenURI(newItemId, tokenURI);
        emit Minted(newItemId, to, tokenURI);
    }

    /**
     * @notice Transfers an NFT from one address to another.
     * @dev Only government or the token owner can transfer NFTs.
     * @param from The current owner of the NFT.
     * @param to The new owner of the NFT.
     * @param tokenId The ID of the NFT to transfer.
     */
    function transferNFT(address from, address to, uint256 tokenId) public {
        require(
            hasRole(GOVERNMENT, msg.sender) || ownerOf(tokenId) == msg.sender,
            "Only government or token owner can transfer"
        );
        require(hasRole(CITIZEN, to), "Recipient must be a citizen");
        _transfer(from, to, tokenId);
        emit Transferred(tokenId, from, to);
    }

    /**
     * @notice Burns an NFT.
     * @dev Only government can burn NFTs.
     * @param tokenId The ID of the NFT to burn.
     */
    function burnNFT(uint256 tokenId) public onlyRole(GOVERNMENT) {
        _burn(tokenId);
        emit Burned(tokenId);
    }

    /**
     * @notice Checks if an address is a citizen.
     * @param account The address to check.
     * @return True if the address has the citizen role, false otherwise.
     */
    function isCitizen(address account) public view returns (bool) {
        return hasRole(CITIZEN, account);
    }

    // The following functions are overrides required by Solidity
    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    // Events
    event Minted(uint256 indexed tokenId, address indexed to, string tokenURI);
    event Transferred(uint256 indexed tokenId, address indexed from, address indexed to);
    event Burned(uint256 indexed tokenId);
    event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);
    event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);
}
